with metrics as (select id, store_id, product_id, quantity, last_restock, avg(quantity) over (partition by product_id, store_id order by quantity, id rows between 2 preceding and 1 preceding) as quantity_avg_2_prior, percent_rank() over (partition by product_id order by quantity desc nulls last) as quantity_percent_rank from inventory) select id, store_id, quantity, last_restock from metrics;
